local PitchforkMaker = {}
local PRODUCTS = {
    simple_wood_pitchfork = { name = "Preproste lesene vile", woodCost = 3, ironCost = 1, time = 3, cost = 50, food = 10, happiness = 1, description = "Preproste lesene vile za premetavanje." },
    iron_tined_pitchfork = { name = "Železnovile vile", woodCost = 2, ironCost = 2, time = 5, cost = 140, food = 18, happiness = 1, prestige = 2, description = "Železnovile vile za trgovce." },
    steel_tined_pitchfork = { name = "Jeklenovile vile", woodCost = 2, ironCost = 2, steelCost = 1, time = 8, cost = 340, food = 28, happiness = 2, prestige = 6, description = "Jeklenovile vile za plemiče." },
    silver_trimmed_pitchfork = { name = "Srebrnoobrobljene vile", woodCost = 2, ironCost = 2, silverCost = 1, steelCost = 1, time = 12, cost = 800, food = 40, happiness = 3, prestige = 14, description = "Srebrnoobrobljene vile za visoke plemiče." },
    gold_trimmed_pitchfork = { name = "Zlatookrasne vile", woodCost = 2, ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, jewelCost = 1, time = 16, cost = 1800, food = 55, happiness = 5, prestige = 27, description = "Vile z draguljem za visoko plemstvo." },
    royal_grand_pitchfork = { name = "Kraljevski veliki vile", woodCost = 4, ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 4000, food = 75, happiness = 12, prestige = 58, description = "Velike kraljevske vile z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    pitchfork_workshop = { name = "Vilna delavnica", cost = { gold = 240, wood = 140, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 880, wood = 300, stone = 240, silver = 6, steel = 4 }, upkeep = 20, qualityBonus = 18 },
    master_pitchfork_atelier = { name = "Mojstrski vilni atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
PitchforkMaker.woodStock = 16; PitchforkMaker.ironStock = 14; PitchforkMaker.steelStock = 8; PitchforkMaker.silverStock = 6; PitchforkMaker.goldStock = 6; PitchforkMaker.jewelStock = 4; PitchforkMaker.pearlStock = 4
PitchforkMaker.productStock = {}; PitchforkMaker.buildings = {}; PitchforkMaker.maker = nil; PitchforkMaker.activeMaking = {}; PitchforkMaker.totalProducts = 0; PitchforkMaker.dayTimer = 0
function PitchforkMaker.init() PitchforkMaker.woodStock=16; PitchforkMaker.ironStock=14; PitchforkMaker.steelStock=8; PitchforkMaker.silverStock=6; PitchforkMaker.goldStock=6; PitchforkMaker.jewelStock=4; PitchforkMaker.pearlStock=4; PitchforkMaker.productStock={}; PitchforkMaker.buildings={}; PitchforkMaker.maker=nil; PitchforkMaker.activeMaking={}; PitchforkMaker.totalProducts=0; PitchforkMaker.dayTimer=0; print("[PitchforkMaker] Royal Pitchfork Maker System initialized (6 products, 4 buildings)") end
function PitchforkMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PitchforkMaker.maker={name=n or ("Vilar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vilar najet: %s (spretnost: %d)",PitchforkMaker.maker.name,s),"success") end; return true end
function PitchforkMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PitchforkMaker.build(id) local ok,e=PitchforkMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PitchforkMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PitchforkMaker.getQualityBonus() local b=0; for _,bd in ipairs(PitchforkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PitchforkMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PitchforkMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PitchforkMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and PitchforkMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and PitchforkMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PitchforkMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PitchforkMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PitchforkMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PitchforkMaker.buildings==0 then return false,"Potrebna vilna delavnica" end; if not PitchforkMaker.maker then return false,"Potreben vilar" end; return true end
function PitchforkMaker.make(pt,qty) qty=qty or 1; local ok,e=PitchforkMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PitchforkMaker.woodStock=PitchforkMaker.woodStock-d.woodCost*qty end; if d.ironCost then PitchforkMaker.ironStock=PitchforkMaker.ironStock-d.ironCost*qty end; if d.steelCost then PitchforkMaker.steelStock=PitchforkMaker.steelStock-d.steelCost*qty end; if d.silverCost then PitchforkMaker.silverStock=PitchforkMaker.silverStock-d.silverCost*qty end; if d.goldCost then PitchforkMaker.goldStock=PitchforkMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PitchforkMaker.jewelStock=PitchforkMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PitchforkMaker.pearlStock=PitchforkMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PitchforkMaker.maker then t=math.max(1,t-math.floor(PitchforkMaker.maker.skill/13)) end; table.insert(PitchforkMaker.activeMaking,{id="pitchfork_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PitchforkMaker.completeMaking(m) local q=1.0+(PitchforkMaker.getQualityBonus()/100); if PitchforkMaker.maker then q=q+(PitchforkMaker.maker.skill/140) end; q=math.min(2.5,q); PitchforkMaker.productStock[m.productType]=(PitchforkMaker.productStock[m.productType] or 0)+m.quantity; PitchforkMaker.totalProducts=PitchforkMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PitchforkMaker.maker then PitchforkMaker.maker.itemsMade=PitchforkMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PitchforkMaker.maker.skill=math.min(100,PitchforkMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vile izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pitchfork.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function PitchforkMaker.update(dt) if not _G.state then return end; PitchforkMaker.dayTimer=PitchforkMaker.dayTimer+dt; if PitchforkMaker.dayTimer>=30 then PitchforkMaker.dayTimer=0; for i=#PitchforkMaker.activeMaking,1,-1 do local m=PitchforkMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PitchforkMaker.completeMaking(m); table.remove(PitchforkMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PitchforkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PitchforkMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PitchforkMaker.getStats() return {woodStock=PitchforkMaker.woodStock,ironStock=PitchforkMaker.ironStock,steelStock=PitchforkMaker.steelStock,silverStock=PitchforkMaker.silverStock,goldStock=PitchforkMaker.goldStock,jewelStock=PitchforkMaker.jewelStock,pearlStock=PitchforkMaker.pearlStock,productStock=PitchforkMaker.productStock,numBuildings=#PitchforkMaker.buildings,hasMaker=PitchforkMaker.maker~=nil,makerName=PitchforkMaker.maker and PitchforkMaker.maker.name or "—",makerSkill=PitchforkMaker.maker and PitchforkMaker.maker.skill or 0,activeMaking=#PitchforkMaker.activeMaking,totalProducts=PitchforkMaker.totalProducts} end
return PitchforkMaker
